// 📊 DEBUG COLLECTEUR - Affichage complet
const fullInput = $input.item;
console.log('🔍 FULL INPUT STRUCTURE:', JSON.stringify(fullInput, null, 2));

const webhookData = fullInput.json.body;
console.log('📊 WEBHOOK DATA:', JSON.stringify(webhookData, null, 2));

if (!webhookData?.contenu) {
  throw new Error('WEBHOOK STRUCTURE PROBLEM: ' + JSON.stringify(fullInput.json));
}

return {
  json: {
    contenu_original: webhookData.contenu,
    collecteur_status: 'webhook_data_extracted',
    debug_info: {
      full_input_keys: Object.keys(fullInput),
      json_keys: Object.keys(fullInput.json),
      body_keys: Object.keys(webhookData),
      contenu_preview: webhookData.contenu.substring(0, 200)
    }
  },
  binary: fullInput.binary || {}
};

// 🔍 DEBUG FUSION - Analyse détaillée du parsing
const allInputs = $input.all();
console.log('🔍 === DEBUG FUSION COMPLET ===');
console.log('Nombre d\'inputs:', allInputs.length);

allInputs.forEach((input, index) => {
  console.log(`\n--- INPUT ${index} ---`);
  console.log('Keys:', input.json ? Object.keys(input.json) : 'no json');
  console.log('Is collector:', !!(input.json?.collecteur_status));
  console.log('Is array (OpenAI):', Array.isArray(input.json));

  if (Array.isArray(input.json)) {
    console.log('Array length:', input.json.length);
    console.log('First element keys:', input.json[0] ? Object.keys(input.json[0]) : 'empty');
    console.log('Has message:', !!(input.json[0]?.message));
    console.log('Message content preview:', input.json[0]?.message?.content?.substring(0, 100));
  }
});

// Identifier les données
let collectorData = allInputs.find(input => input.json?.collecteur_status);
let openAIData = allInputs.find(input => Array.isArray(input.json) && input.json[0]?.message);

console.log('\n--- IDENTIFICATION ---');
console.log('Collector found:', !!collectorData);
console.log('OpenAI found:', !!openAIData);

if (!openAIData) {
  console.log('❌ OPENAI DATA MISSING!');
  return {
    json: {
      error: 'OpenAI data not found',
      all_inputs_debug: allInputs.map((input, i) => ({
        index: i,
        has_json: !!input.json,
        is_array: Array.isArray(input.json),
        keys: input.json ? Object.keys(input.json) : []
      }))
    }
  };
}

// Parser l'IA
const aiResponse = openAIData.json[0].message.content;
console.log('\n--- PARSING AI ---');
console.log('Raw AI response:', aiResponse);

let parsed;
try {
  const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
  console.log('Cleaned response:', cleanResponse);
  parsed = JSON.parse(cleanResponse);
  console.log('✅ PARSED SUCCESSFULLY:', parsed);
} catch (e) {
  console.log('❌ PARSING FAILED:', e.message);
  parsed = { title: 'PARSE ERROR', subtitle: 'PARSE ERROR', body: 'PARSE ERROR' };
}

return {
  json: {
    ai_title: parsed.title || 'NO TITLE',
    ai_subtitle: parsed.subtitle || 'NO SUBTITLE',
    ai_body: parsed.body || 'NO BODY',

    debug_final: {
      raw_response: aiResponse,
      parsed_result: parsed,
      parsing_success: !!(parsed.title && parsed.subtitle && parsed.body),
      collector_content: collectorData?.json?.contenu_original?.substring(0, 100)
    }
  }
};
